=== Migrations.swift (registry) ===
import Foundation

/// Migration 001 — core infrastructure only.
///
/// IMPORTANT, READ BEFORE ADDING TABLES HERE.
///
/// Technical Specification v1.0 defines a 48-table domain schema. That text is
/// not available to this package, so **none of those 48 tables are invented
/// here**. This migration creates only the tables AlmanacCore itself owns and
/// can define from first principles: the sync anchor store and the backup
/// manifest. The domain schema belongs in migration 002 and must be
/// transcribed from the spec, not reconstructed.
///
/// If the spec's own build order names the 48-table migration "Migration_001",
/// renumber this one to 000 or fold it into 001 at that point — nothing has
/// shipped, so the renumber is free today and expensive after the first install.
public enum Migration001_CoreInfrastructure: Migration {
    public static let version = 1
    public static let name = "core_infrastructure"

    public static func up(_ db: Database) throws {
        try db.execute("""
        CREATE TABLE sync_anchor (
            domain        TEXT    PRIMARY KEY,
            anchor_token  BLOB,
            last_synced   TEXT,
            last_error    TEXT
        );
        """)

        try db.execute("""
        CREATE TABLE backup_manifest (
            id            INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at    TEXT    NOT NULL,
            schema_version INTEGER NOT NULL,
            byte_count    INTEGER NOT NULL,
            sha256        TEXT    NOT NULL,
            note          TEXT
        );
        """)

        try db.execute("""
        CREATE INDEX idx_backup_manifest_created_at
            ON backup_manifest (created_at DESC);
        """)
    }
}

/// The migration list the app runs at launch. Append only.
public enum AlmanacMigrations {
    public static let all: [any Migration.Type] = [
        Migration001_CoreInfrastructure.self,
        Migration002_LaboratoryCatalog.self,
        Migration003_LaboratoryRecords.self,
        Migration004_HealthSamples.self,
        Migration005_SpecimenAndCatalogSemantics.self,
        Migration006_EditingAndSourceOrdering.self,
        Migration007_ConflictResolution.self,
        Migration008_NutritionReference.self,
        Migration009_NutritionLog.self,
        Migration010_NutritionPortionsAndDishes.self,
        Migration011_PortionIdentity.self
        // The Technical Spec v1.0 48-table schema is still unavailable and is
        // still not authored from inference. Numbering for it is settled per
        // docs/architecture/health-data-foundation.md §11, and renumbering
        // 002-004 stays free until a durable database exists.
    ]
}

=== Migration009 (nutrition_log) ===
import Foundation

/// Migration 009 — the food log.
///
/// Appended; 001-008 are untouched.
///
/// The reference database answers "what is in this food". Nothing recorded
/// "the user ate 150 g of it". That is this table.
///
/// Two decisions worth the words:
///
/// 1. **`food_ref` is text, with no foreign key.** It holds a
///    `SourceIdentifier` — `usda:1105904`, `almanac:dish-kabsa`. Processing
///    Design v0.1 §3 keeps "remove a whole source" a one-line delete when a
///    rights holder says no; a foreign key with ON DELETE CASCADE would turn
///    that delete into the erasure of the user's own meal history. The log is
///    the user's record, not the publisher's, and it outlives the reference
///    rows it points at. `food_name_text` is what keeps an orphaned row
///    readable.
/// 2. **`grams` is nullable.** "Some rice, amount not stated" is a thing a
///    person logs, and `NutrientQualifier` already establishes that this
///    codebase does not write a number where nobody supplied one. An entry
///    with no amount yields no energy and says so, rather than yielding zero.
///
/// Energy is deliberately not a column here. It is a derivation from the
/// reference values and the grams, and storing it would freeze one answer to
/// a question whose inputs get corrected.
public enum Migration009_NutritionLog: Migration {
    public static let version = 9
    public static let name = "nutrition_log"

    public static func up(_ db: Database) throws {
        try db.execute("""
        CREATE TABLE nutrition_log (
            id                          TEXT    PRIMARY KEY,
            source_system               TEXT    NOT NULL,
            external_id                 TEXT,
            food_ref                    TEXT    NOT NULL,
            food_name_text              TEXT,
            grams                       REAL,
            quantity_text               TEXT,
            eaten_at                    TEXT,
            eaten_precision             TEXT    NOT NULL,
            eaten_tz_offset_minutes     INTEGER,
            eaten_tz_id                 TEXT,
            recorded_at                 TEXT    NOT NULL,
            recorded_tz_offset_minutes  INTEGER,
            deleted_at                  TEXT
        );
        """)

        // Identity is (source_system, external_id), as for health_sample: the
        // same string from a different source is a different meal. Manual
        // entries carry no external id and are therefore never deduplicated
        // against each other — eating the same food twice is not a replay.
        try db.execute("""
        CREATE UNIQUE INDEX idx_nutrition_log_source
            ON nutrition_log (source_system, external_id)
            WHERE external_id IS NOT NULL;
        """)
        try db.execute("CREATE INDEX idx_nutrition_log_time ON nutrition_log (eaten_at);")
        try db.execute("CREATE INDEX idx_nutrition_log_food ON nutrition_log (food_ref);")

        // One revision table, not two. A log entry is small enough that "what
        // was eaten" and "how much, when" are one fact; Laboratory splits them
        // only because a result's content and its metadata are revised by
        // different actors for different reasons.
        try db.execute("""
        CREATE TABLE nutrition_log_revision (
            id                      TEXT    PRIMARY KEY,
            log_id                  TEXT    NOT NULL
                                        REFERENCES nutrition_log(id) ON DELETE CASCADE,
            revision_number         INTEGER NOT NULL,
            food_ref                TEXT    NOT NULL,
            food_name_text          TEXT,
            grams                   REAL,
            quantity_text           TEXT,
            eaten_at                TEXT,
            eaten_precision         TEXT    NOT NULL,
            eaten_tz_offset_minutes INTEGER,
            eaten_tz_id             TEXT,
            changed_fields          TEXT    NOT NULL,
            actor                   TEXT    NOT NULL,
            reason_text             TEXT,
            recorded_at             TEXT    NOT NULL
        );
        """)
        try db.execute("""
        CREATE UNIQUE INDEX idx_nutrition_log_revision_number
            ON nutrition_log_revision (log_id, revision_number);
        """)
    }
}

=== Migration011 ===
import Foundation

/// Migration 011 — a portion is not duplicated by re-importing it.
///
/// Appended; 001-010 are untouched, on the rule this repository already
/// follows that a committed migration is treated the same as an applied one.
///
/// **The defect.** `nutrition_portion` carried no uniqueness at all, so calling
/// `addPortion` twice with the same row — which is what re-running an importer
/// does — stored it twice. Two identical "1 cup" rows are then reported as
/// `PortionMatch.ambiguous`, and `grams(of:amount:unit:)` returns nil rather
/// than the weight. A phantom disagreement between a row and itself, presented
/// to the user as a measure that cannot be resolved.
///
/// The key is everything that makes two measures genuinely different: the
/// food, the folded unit, the modifier, the stated amount and the gram
/// weight. USDA really does carry several "1 cup" rows per food with
/// different weights, and those must still coexist — this rejects only a row
/// identical to one already held. `COALESCE(modifier_text, '')` is not
/// decoration: SQLite treats NULLs as distinct in a unique index, so without
/// it the unmodified rows — the common case — would go on duplicating.
public enum Migration011_PortionIdentity: Migration {
    public static let version = 11
    public static let name = "portion_identity"

    public static func up(_ db: Database) throws {
        // Any duplicate already stored is collapsed before the index is built,
        // keeping the first by id so the choice is not row order.
        try db.execute("""
        DELETE FROM nutrition_portion WHERE id NOT IN (
            SELECT MIN(id) FROM nutrition_portion
            GROUP BY food_ref, unit_fold, COALESCE(modifier_text, ''), amount, gram_weight
        );
        """)
        try db.execute("""
        CREATE UNIQUE INDEX idx_nutrition_portion_identity
            ON nutrition_portion (food_ref, unit_fold, COALESCE(modifier_text, ''),
                                  amount, gram_weight);
        """)
    }
}

=== HealthProvider.swift ===
import Foundation

/// The seam where HealthKit will sit.
///
/// HealthKit does not exist on Linux, so it cannot be imported by this target
/// at all. That constraint is useful rather than annoying: it forces the sync
/// algorithm to be written against a protocol and tested against a fake, and
/// keeps `HKHealthStore` confined to one iOS-only file in the app target.
///
/// The concrete `HealthKitProvider` belongs in the iOS target and is the only
/// place `import HealthKit` may appear.
public protocol HealthProvider: Sendable {
    func requestAuthorisation(for domains: [HealthDomain]) async throws
    /// Returns samples changed since `anchor`, plus the anchor to store next.
    func changes(in domain: HealthDomain, since anchor: [UInt8]?) async throws -> HealthChangeSet
}

/// Domains Almanac syncs. Names are Almanac's, not HealthKit's — the mapping
/// to HKQuantityType/HKCategoryType lives in the iOS adapter, per the spec's
/// HealthKit map (which is not available here and must not be guessed).
public enum HealthDomain: String, Codable, Sendable, CaseIterable, Hashable {
    case sleep, workouts, activeEnergy, restingEnergy, steps, heartRate, hrv, bodyMass
}

public struct HealthSample: Sendable, Hashable {
    public let externalID: String
    public let domain: HealthDomain
    public let start: Date
    public let end: Date
    public let value: Double?
    public let unit: String?
    public let sourceName: String?

    public init(externalID: String, domain: HealthDomain, start: Date, end: Date,
                value: Double?, unit: String?, sourceName: String? = nil) {
        self.externalID = externalID
        self.domain = domain
        self.start = start
        self.end = end
        self.value = value
        self.unit = unit
        self.sourceName = sourceName
    }
}

public struct HealthChangeSet: Sendable {
    public let added: [HealthSample]
    public let deletedExternalIDs: [String]
    public let nextAnchor: [UInt8]?

    public init(added: [HealthSample], deletedExternalIDs: [String], nextAnchor: [UInt8]?) {
        self.added = added
        self.deletedExternalIDs = deletedExternalIDs
        self.nextAnchor = nextAnchor
    }
}

public enum HealthProviderError: Error, Sendable {
    case authorisationDenied(HealthDomain)
    case unavailable
}

/// In-memory provider used by tests and by any non-iOS host.
public final class FakeHealthProvider: HealthProvider, @unchecked Sendable {
    private let lock = NSLock()
    private var batches: [HealthDomain: [HealthChangeSet]] = [:]
    public private(set) var authorisedDomains: Set<HealthDomain> = []

    public init() {}

    public func enqueue(_ set: HealthChangeSet, for domain: HealthDomain) {
        lock.lock(); defer { lock.unlock() }
        batches[domain, default: []].append(set)
    }

    public func requestAuthorisation(for domains: [HealthDomain]) async throws {
        authorise(domains)
    }

    public func changes(in domain: HealthDomain, since anchor: [UInt8]?) async throws -> HealthChangeSet {
        try nextChangeSet(domain, anchor)
    }

    // Locks are taken only in synchronous helpers, never held across a suspension.
    private func authorise(_ domains: [HealthDomain]) {
        lock.lock(); defer { lock.unlock() }
        authorisedDomains.formUnion(domains)
    }

    private func nextChangeSet(_ domain: HealthDomain, _ anchor: [UInt8]?) throws -> HealthChangeSet {
        lock.lock(); defer { lock.unlock() }
        guard authorisedDomains.contains(domain) else {
            throw HealthProviderError.authorisationDenied(domain)
        }
        guard var queue = batches[domain], !queue.isEmpty else {
            return HealthChangeSet(added: [], deletedExternalIDs: [], nextAnchor: anchor)
        }
        let next = queue.removeFirst()
        batches[domain] = queue
        return next
    }
}

=== HealthSampleStore.swift ===
import Foundation

public struct HealthApplyCounts: Sendable, Hashable {
    public let inserted: Int
    public let updated: Int
    public let deleted: Int
    public init(inserted: Int, updated: Int, deleted: Int) {
        self.inserted = inserted; self.updated = updated; self.deleted = deleted
    }
    public static let zero = HealthApplyCounts(inserted: 0, updated: 0, deleted: 0)
}

/// Writes a change set. **Must not open its own transaction** — the caller
/// owns it, because the rows and the cursor advance have to commit together.
public protocol HealthSampleWriting: Sendable {
    func apply(_ changeSet: HealthChangeSet, in db: Database) throws -> HealthApplyCounts
}

/// Persists samples for one `HealthDomain`. This slice wires up `.bodyMass`
/// only; the table and this type are domain-agnostic, but no other domain is
/// enabled, tested, or claimed to work.
public struct HealthSampleStore: HealthSampleWriting, TimelineProviding, @unchecked Sendable {
    public let domain: String
    public let healthDomain: HealthDomain
    public let sourceSystem: String
    private let db: Database
    private let clock: any Clock
    private let zone: ZoneContext

    public init(db: Database, healthDomain: HealthDomain = .bodyMass,
                sourceSystem: String = "healthkit",
                clock: any Clock = SystemClock(),
                zone: ZoneContext = ZoneContext(TimeZone.current)) {
        self.db = db
        self.healthDomain = healthDomain
        self.sourceSystem = sourceSystem
        self.domain = healthDomain.rawValue
        self.clock = clock
        self.zone = zone
    }

    private var nowText: String { ISO8601DateFormatter().string(from: clock.now) }
    private func iso(_ date: Date) -> String { ISO8601DateFormatter().string(from: date) }

    @discardableResult
    public func apply(_ changeSet: HealthChangeSet, in db: Database) throws -> HealthApplyCounts {
        var inserted = 0, updated = 0, deleted = 0

        for sample in changeSet.added where sample.domain == healthDomain {
            let existing = try db.query("""
                SELECT id FROM health_sample WHERE source_system = ? AND external_id = ?;
                """, [.text(sourceSystem), .text(sample.externalID)]).first?.string("id")
            // Identity is (source_system, external_id): the same string from a
            // different source is a different sample, never an update of this one.
            try db.run("""
            INSERT INTO health_sample
                (id, source_system, external_id, domain, start_at, end_at, value, unit,
                 source_name, recorded_at, recorded_tz_offset_minutes, deleted_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL)
            ON CONFLICT(source_system, external_id) DO UPDATE SET
                start_at    = excluded.start_at,
                end_at      = excluded.end_at,
                value       = excluded.value,
                unit        = excluded.unit,
                source_name = excluded.source_name,
                recorded_at = excluded.recorded_at,
                deleted_at  = NULL;
            """, [
                .text(existing ?? UUID().uuidString), .text(sourceSystem),
                .text(sample.externalID), .text(sample.domain.rawValue),
                .text(iso(sample.start)), .text(iso(sample.end)),
                sample.value.map { SQLValue.real($0) } ?? .null,
                sample.unit.map { SQLValue.text($0) } ?? .null,
                sample.sourceName.map { SQLValue.text($0) } ?? .null,
                .text(nowText),
                zone.offsetMinutes.map { SQLValue.integer(Int64($0)) } ?? .null
            ])
            if existing == nil { inserted += 1 } else { updated += 1 }
        }

        // Soft delete. A source withdrawing a sample is a fact about the
        // source, not permission to erase what was already recorded.
        for externalID in changeSet.deletedExternalIDs {
            deleted += try db.run("""
                UPDATE health_sample SET deleted_at = ?
                WHERE source_system = ? AND external_id = ? AND deleted_at IS NULL;
                """, [.text(nowText), .text(sourceSystem), .text(externalID)])
        }

        return HealthApplyCounts(inserted: inserted, updated: updated, deleted: deleted)
    }

    public func liveSampleCount() throws -> Int {
        Int(try db.query("""
            SELECT COUNT(*) AS n FROM health_sample
            WHERE source_system = ? AND domain = ? AND deleted_at IS NULL;
            """, [.text(sourceSystem), .text(healthDomain.rawValue)])
            .first?.int("n") ?? 0)
    }

    public func isDeleted(externalID: String) throws -> Bool {
        guard let row = try db.query("""
            SELECT deleted_at FROM health_sample WHERE source_system = ? AND external_id = ?;
            """, [.text(sourceSystem), .text(externalID)]).first else { return false }
        return !row.isNull("deleted_at")
    }

    public func entries(from: String, to: String) throws -> [TimelineEntry] {
        guard let range = DateRange(from: from, to: to) else { return [] }
        // Normalised to UTC before it reaches SQL. `start_at` is stored as a
        // UTC `...Z` string, so comparing it lexically against a caller's
        // `+03:00` text would be wrong by three hours — and silently so.
        let bounds = range.utcTextBounds
        return try db.query("""
        SELECT id, external_id, start_at, value, unit, source_name
        FROM health_sample
        WHERE source_system = ? AND domain = ? AND deleted_at IS NULL
          AND start_at >= ? AND start_at < ?
        ORDER BY start_at;
        """, [.text(sourceSystem), .text(healthDomain.rawValue),
              .text(bounds.start), .text(bounds.end)])
        .compactMap { row in
            // Samples always carry a full instant, so their span is a point and
            // the fit is always `.definite`. Computed through the same API as
            // Laboratory so the two domains cannot drift apart on what a range
            // means.
            guard let id = row.string("id"), let start = row.string("start_at"),
                  let occurrence = PartialDateTime(storedText: start, precision: .instant,
                                                   zone: .unknown),
                  let fit = occurrence.fit(in: range) else { return nil }
            let value: ValuePresentation
            if let v = row.double("value") {
                value = .quantity(text: String(v), unit: row.string("unit"))
            } else {
                value = .missing(reason: LabMissingReason.notReportedBySource.rawValue)
            }
            return TimelineEntry(
                domain: domain, kind: "sample", recordTable: "health_sample", recordID: id,
                occurrence: occurrence, basis: .occurrence,
                title: healthDomain.rawValue, detail: row.string("source_name"),
                value: value, lifecycle: nil, rangeFit: fit)
        }
    }
}

=== HealthSyncService.swift ===
import Foundation

public struct SyncOutcome: Sendable, Hashable {
    public let counts: HealthApplyCounts
    public let advancedTo: [UInt8]?
}

/// One incremental sync, with the property that matters: **the imported rows
/// and the cursor advance commit together.**
///
/// The read from the provider happens outside the transaction; only the write
/// is inside it. If the write throws, the transaction rolls back and the anchor
/// keeps its previous value, so the next run re-reads the same range. An anchor
/// that advanced past rows that were never persisted would skip them for good.
public struct HealthSyncService: Sendable {
    private let db: Database
    private let provider: any HealthProvider
    private let anchors: SyncAnchorStore
    private let writer: any HealthSampleWriting
    private let healthDomain: HealthDomain
    private let anchorKey: String

    public init(db: Database, provider: any HealthProvider, writer: any HealthSampleWriting,
                healthDomain: HealthDomain = .bodyMass, clock: any Clock = SystemClock(),
                anchorKey: String? = nil) {
        self.db = db
        self.provider = provider
        self.writer = writer
        self.healthDomain = healthDomain
        self.anchors = SyncAnchorStore(db: db, clock: clock)
        self.anchorKey = anchorKey ?? healthDomain.rawValue
    }

    public func currentAnchor() throws -> [UInt8]? {
        try anchors.load(anchorKey)?.token
    }

    @discardableResult
    public func syncOnce() async throws -> SyncOutcome {
        let previous = try anchors.load(anchorKey)?.token
        let changeSet = try await provider.changes(in: healthDomain, since: previous)
        do {
            return try db.transaction {
                let counts = try writer.apply(changeSet, in: db)
                try anchors.save(domain: anchorKey, token: changeSet.nextAnchor)
                return SyncOutcome(counts: counts, advancedTo: changeSet.nextAnchor)
            }
        } catch {
            // The rows and the advance both rolled back. Record why, without
            // clearing the last good anchor.
            try? anchors.recordFailure(domain: anchorKey, message: String(describing: error))
            throw error
        }
    }
}

=== SyncAnchorStore.swift ===
import Foundation

/// A HealthKit-style incremental sync anchor, persisted per domain.
///
/// The anchor is an opaque blob on purpose: HKQueryAnchor archives to Data and
/// this core must not know that. On Linux the same store is exercised with
/// arbitrary bytes.
public struct SyncAnchor: Sendable, Hashable {
    public let domain: String
    public let token: [UInt8]?
    public let lastSynced: Date?
    public let lastError: String?

    public init(domain: String, token: [UInt8]?, lastSynced: Date?, lastError: String? = nil) {
        self.domain = domain
        self.token = token
        self.lastSynced = lastSynced
        self.lastError = lastError
    }
}

public struct SyncAnchorStore: Sendable {
    private let db: Database
    private let clock: any Clock

    public init(db: Database, clock: any Clock = SystemClock()) {
        self.db = db
        self.clock = clock
    }

    public func load(_ domain: String) throws -> SyncAnchor? {
        let rows = try db.query(
            "SELECT domain, anchor_token, last_synced, last_error FROM sync_anchor WHERE domain = ?;",
            [.text(domain)]
        )
        guard let row = rows.first else { return nil }
        var token: [UInt8]?
        if case .blob(let bytes)? = row["anchor_token"] { token = bytes }
        let synced = row.string("last_synced").flatMap { ISO8601DateFormatter().date(from: $0) }
        return SyncAnchor(domain: domain, token: token, lastSynced: synced,
                          lastError: row.string("last_error"))
    }

    public func save(domain: String, token: [UInt8]?) throws {
        try db.run("""
        INSERT INTO sync_anchor (domain, anchor_token, last_synced, last_error)
        VALUES (?, ?, ?, NULL)
        ON CONFLICT(domain) DO UPDATE SET
            anchor_token = excluded.anchor_token,
            last_synced  = excluded.last_synced,
            last_error   = NULL;
        """, [
            .text(domain),
            token.map { SQLValue.blob($0) } ?? .null,
            .text(ISO8601DateFormatter().string(from: clock.now))
        ])
    }

    /// Records a failure without clearing the last good anchor — a failed sync
    /// must never cause the next one to re-import from the beginning.
    public func recordFailure(domain: String, message: String) throws {
        try db.run("""
        INSERT INTO sync_anchor (domain, anchor_token, last_synced, last_error)
        VALUES (?, NULL, NULL, ?)
        ON CONFLICT(domain) DO UPDATE SET last_error = excluded.last_error;
        """, [.text(domain), .text(message)])
    }
}
=== Timeline dir ===
Timeline.swift
TimelineEntry.swift
import Foundation

/// Which of a record's times the timeline placed it by.
///
/// `recorded` means the record carried no occurrence or report time and fell
/// back to when it was entered into Almanac. That is a materially weaker
/// claim, so it travels with the entry rather than being smoothed away.
public enum TimeBasis: String, Codable, Sendable, Hashable {
    case occurrence, reported, recorded
}

/// How a module chose to present its value.
///
/// Deliberately not a number and not a Bool. Missing, qualitative and bounded
/// values are three different facts, and the timeline never reinterprets what
/// a module formatted.
public enum ValuePresentation: Sendable, Hashable {
    case none
    case quantity(text: String, unit: String?)
    case bounded(comparator: String, text: String, unit: String?)
    case coded(text: String)
    case narrative(text: String)
    case ratio(text: String)
    case titer(text: String)
    case missing(reason: String)
    case derived(text: String, ruleVersion: String)
}

public struct TimelineEntry: Sendable, Hashable {
    public let domain: String
    public let kind: String
    public let recordTable: String
    public let recordID: String
    public let occurrence: PartialDateTime
    public let basis: TimeBasis
    public let title: String
    public let detail: String?
    public let value: ValuePresentation
    public let lifecycle: String?
    /// Whether the record definitely falls in the queried range, or merely
    /// overlaps it because its date is coarser than the range boundary.
